  'check-printer-catalog.mjs','check-printer-catalog-ui.mjs','check-r119-scope.mjs',
  'check-r9-clean-installer.mjs','check-release-portability.mjs','build-and-install-windows.mjs',
]);
const allowedUiTests=new Set(['printer-catalog-fixture.tsx','printer-catalog.html','printer-catalog.mjs']);

const files=(directory,ignore=()=>false)=>{
  const found=[];
  const visit=(current,prefix='')=>{
    for(const entry of fs.readdirSync(current,{withFileTypes:true})){
      const relative=prefix+entry.name;
      if(ignore(relative,entry))continue;
      assert.ok(!entry.isSymbolicLink(),'Unexpected source symlink: '+path.join(directory,relative));
      const absolute=path.join(current,entry.name);
      if(entry.isDirectory())visit(absolute,relative+'/');
      else {assert.ok(entry.isFile(),'Unexpected non-file in source: '+absolute);found.push(relative)}
    }
  };
  visit(directory);return found.sort();
};
let protectedFiles=0;
const exactTree=(label,current,previous,allowed=new Set(),ignore=()=>false)=>{
  assert.ok(fs.existsSync(current)&&fs.existsSync(previous),'Missing checked source tree: '+label);
  const oldPaths=new Set(files(previous,ignore)),newPaths=new Set(files(current,ignore));
  for(const relative of new Set([...oldPaths,...newPaths])){
    if(allowed.has(relative))continue;
    assert.ok(oldPaths.has(relative)&&newPaths.has(relative),'Protected inventory changed: '+label+'/'+relative);
    assert.ok(fs.readFileSync(path.join(previous,relative)).equals(fs.readFileSync(path.join(current,relative))),'Protected file changed: '+label+'/'+relative);
    protectedFiles++;
  }
};
exactTree('src',path.join(root,'src'),path.join(baseline,'src'),allowedSource);
const nativeBaseline=path.join(baseline,fs.existsSync(path.join(baseline,'src-tauri'))?'src-tauri':'native');
exactTree('src-tauri',path.join(root,'src-tauri'),nativeBaseline,new Set(),relative=>/^(?:target|binaries)(?:\/|$)/.test(relative));
exactTree('scripts',path.join(root,'scripts'),path.join(baseline,'scripts'),allowedScripts);
exactTree('ui-tests',path.join(root,'ui-tests'),path.join(baseline,'ui-tests'),allowedUiTests,relative=>/^node_modules(?:\/|$)/.test(relative));
if(fs.existsSync(path.join(baseline,'public')))exactTree('public',path.join(root,'public'),path.join(baseline,'public'),new Set(),relative=>/^camera-detector\/\.obico-failure-5a6b1be1fa\.onnx\.[A-Za-z0-9]{6}$/.test(relative));
for(const relative of ['package-lock.json','tsconfig.json','vite.config.ts','index.html','.gitattributes','FIX_AND_INSTALL.bat']){
  assert.ok(fs.readFileSync(path.join(baseline,relative)).equals(fs.readFileSync(path.join(root,relative))),'Protected build configuration changed: '+relative);
  protectedFiles++;
}

// Release identity may change without changing package versions, dependencies,
// installer identifiers, the updater endpoint or the existing signing key.
const oldPackage=JSON.parse(read(baseline,'package.json')),newPackage=JSON.parse(read(root,'package.json'));
assert.deepEqual({...newPackage,scripts:undefined},{...oldPackage,scripts:undefined},'Package version, dependencies or other package metadata changed');
