  'check:printer-catalog':'node scripts/check-printer-catalog.mjs',
  'check:r119-scope':'node scripts/check-r119-scope.mjs',
};
assert.deepEqual(newPackage.scripts,{...oldPackage.scripts,...scriptAdditions},'Existing npm commands changed or an unapproved command was added');
const oldChannel=JSON.parse(read(baseline,'UPDATE-CHANNEL.json')),newChannel=JSON.parse(read(root,'UPDATE-CHANNEL.json'));
assert.equal(oldChannel.installedSequence,118,'Baseline update sequence is not R118');
assert.equal(newChannel.installedSequence,119,'R119 update sequence must be 119');
assert.deepEqual({...newChannel,installedSequence:118},oldChannel,'Stable updater endpoint, channel or signing public key changed');
const identityEdits={
  'scripts/check-r9-clean-installer.mjs':value=>value.replaceAll(oldBuild,newBuild).replace('wrong R117 build identity','wrong R119 build identity'),
  'scripts/check-release-portability.mjs':value=>value.replaceAll(oldBuild,newBuild).replace('release build identity is not R117 frontend/native contract','release build identity is not R119 frontend/native contract'),
  'scripts/build-and-install-windows.mjs':value=>value.replace('Klipper Farm v1.14.5 - R118 Background and Panels','Klipper Farm v1.14.5 - R119 Printer Catalog'),
};
for(const [relative,updateIdentity] of Object.entries(identityEdits))assert.equal(read(root,relative),updateIdentity(read(baseline,relative)),'Build implementation changed beyond R119 identity: '+relative);

// The catalogue adds one optional metadata field. All other type contracts,
// including the five operational presets, remain the published R118 contracts.
const oldTypes=read(baseline,'src/types.ts'),newTypes=read(root,'src/types.ts');
const catalogField=/\bcatalogModelId\s*\?\s*:\s*string\s*;/g;
assert.equal([...newTypes.matchAll(catalogField)].length,1,'PrinterConfig must add exactly one optional string catalogue ID');
const printer=ts.createPrinter({removeComments:true});
const canonicalSource=(filename,source)=>printer.printFile(ts.createSourceFile(filename,source,ts.ScriptTarget.Latest,true));
assert.equal(canonicalSource('types.ts',newTypes.replace(catalogField,'')),canonicalSource('types.ts',oldTypes),'Operational types changed beyond catalogue metadata');

// Compare every direct native invocation and every printer mutation call,
// including arguments. Formatting and comments do not affect this comparison.
const mutationMethods=new Set(['pause','resume','cancel','emergencyStop','restart','firmwareRestart','start','gcode','setNozzle','setBed','setFan','setSpeed','home','jog','extrude','runMacro','serviceCommand','light','deleteFile','enqueue','queueStart','queuePause','queueRemove','setActiveSpool','upload','cancelUpload']);
const commandCalls=directory=>{
  const calls=[],commands=[];
  for(const relative of files(directory).filter(file=>/\.(?:ts|tsx)$/.test(file))){
    const file=path.join(directory,relative),ast=ts.createSourceFile(file,fs.readFileSync(file,'utf8'),ts.ScriptTarget.Latest,true);
    const visit=node=>{
      if(ts.isCallExpression(node)){
        const native=ts.isIdentifier(node.expression)&&['secureInvoke','invoke'].includes(node.expression.text);
        const mutation=ts.isPropertyAccessExpression(node.expression)&&mutationMethods.has(node.expression.name.text);
        if(native||mutation)calls.push(relative+':'+printer.printNode(ts.EmitHint.Expression,node,ast));
        if(native)commands.push(relative+':'+printer.printNode(ts.EmitHint.Expression,node.arguments[0],ast));
      }
      ts.forEachChild(node,visit);
    };
    visit(ast);
  }
  return {calls:calls.sort(),commands:commands.sort()};
};
const oldCalls=commandCalls(path.join(baseline,'src')),newCalls=commandCalls(path.join(root,'src'));
assert.deepEqual(newCalls.commands,oldCalls.commands,'Native command multiset changed: catalogue selection cannot introduce native commands');
assert.deepEqual(newCalls.calls,oldCalls.calls,'Native invocation or printer mutation call/arguments changed');
for(const relative of ['components/PrinterModelPicker.tsx','lib/printerCatalog.ts','lib/printerCatalogSelection.ts']){
  const source=read(root,'src/'+relative);
  assert.doesNotMatch(source,/\b(?:fetch|XMLHttpRequest|WebSocket|secureInvoke|invoke)\s*(?:<[^()]*>)?\s*\(/,'Offline catalogue code initiates network/native work: '+relative);
  assert.doesNotMatch(source,/\bfrom\s*['"][^'"]*\/(?:moonraker|native|auth)['"]|\bimport\s*\(/,'Catalogue code imports an operational client or dynamic code: '+relative);
}
