import { useId, useMemo, useState } from 'react';
import { Check, ChevronRight, Printer, Search, SlidersHorizontal } from 'lucide-react';
import {
  PRINTER_CATALOG,
  catalogConnectionHint,
  catalogModelArtwork,
  catalogSearchModels,
  getCatalogModel,
  type PrinterCatalogModel
} from '../lib/printerCatalog';
import { ListPagination, usePagedRows } from './ListPagination';
import styles from './PrinterModelPicker.module.css';

const PAGE_SIZE = 24;
const brandCollator = new Intl.Collator('ru', { sensitivity: 'base', numeric: true });
const brandCounts = new Map<string, number>();
for (const entry of PRINTER_CATALOG) brandCounts.set(entry.brand, (brandCounts.get(entry.brand) ?? 0) + 1);
const brands = [...brandCounts.keys()].sort(brandCollator.compare);

function modelName(entry: PrinterCatalogModel) {
  return entry.model.toLocaleLowerCase().startsWith(entry.brand.toLocaleLowerCase())
    ? entry.model
    : `${entry.brand} ${entry.model}`;
}

function geometryLabel(entry: PrinterCatalogModel) {
  const geometry = entry.nominalGeometry;
  return geometry ? `${geometry.x} × ${geometry.y} × ${geometry.z} мм` : undefined;
}

export function PrinterModelPicker({
  selectedId,
  onSelect,
  compact = false
}: {
  selectedId?: string;
  onSelect: (entry: PrinterCatalogModel | undefined) => void;
  compact?: boolean;
}) {
  const id = useId();
  const [query, setQuery] = useState('');
  const [brand, setBrand] = useState('');
  const selected = useMemo(() => getCatalogModel(selectedId), [selectedId]);
  const matches = useMemo(() => catalogSearchModels(query, brand || undefined), [query, brand]);
  const paged = usePagedRows(matches, `${brand}\u0000${query}`, PAGE_SIZE);
  const resetFilters = () => { setQuery(''); setBrand(''); };

  return <section className={`${styles.picker} ${compact ? styles.compact : ''}`} aria-labelledby={`${id}-title`}>
    <header className={styles.header}>
      <div><h3 id={`${id}-title`}>Выберите свой принтер</h3><p>Поиск по производителю и названию модели.</p></div>
      <span className={styles.total}>{PRINTER_CATALOG.length} моделей</span>
    </header>

    <div className={styles.filters}>
      <label className={styles.search} htmlFor={`${id}-search`}>
        <span>Поиск модели</span>
        <div><Search aria-hidden="true"/><input id={`${id}-search`} type="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Например, K1 Max или Ender-3" autoComplete="off" spellCheck={false}/></div>
      </label>
      <label className={styles.brand} htmlFor={`${id}-brand`}>
        <span>Производитель</span>
        <select id={`${id}-brand`} value={brand} onChange={event => setBrand(event.target.value)}>
          <option value="">Все производители</option>
          {brands.map(name => <option key={name} value={name}>{name} ({brandCounts.get(name)})</option>)}
        </select>
      </label>
    </div>

    <button type="button" className={styles.automatic} aria-pressed={!selected} onClick={() => onSelect(undefined)}>
      <SlidersHorizontal aria-hidden="true"/>
      <span><strong>Автоопределение / Моей модели нет</strong><small>Проверить принтер по адресу и настроить вручную.</small></span>
      {!selected ? <Check aria-hidden="true"/> : <ChevronRight aria-hidden="true"/>}
    </button>

    {selected && <div className={styles.selected} aria-live="polite" aria-atomic="true">
      <img src={catalogModelArtwork(selected)} alt="" width="72" height="72" decoding="async"/>
      <div><span className={styles.selectedLabel}><Check aria-hidden="true"/>Выбрана модель</span><strong>{modelName(selected)}</strong><small>{catalogConnectionHint(selected)}</small>{geometryLabel(selected) && <small>Заводская область: {geometryLabel(selected)}</small>}</div>
    </div>}

    <div className={styles.resultsHeading}><span role="status" aria-live="polite" aria-atomic="true">Найдено моделей: <strong>{matches.length}</strong></span>{(query || brand) && <button type="button" onClick={resetFilters}>Сбросить фильтры</button>}</div>

    {matches.length > 0 ? <ul className={styles.grid} aria-label="Модели принтеров">
      {paged.rows.map(entry => {
        const isSelected = entry.id === selectedId;
        const geometry = geometryLabel(entry);
        return <li key={entry.id}>
          <button type="button" className={styles.model} aria-pressed={isSelected} aria-label={`Выбрать ${modelName(entry)}`} onClick={() => onSelect(entry)}>
            <span className={styles.artwork}><img src={catalogModelArtwork(entry)} alt="" width="112" height="96" loading="lazy" decoding="async"/>{isSelected && <span className={styles.selectedMark}><Check aria-hidden="true"/><span>Выбрано</span></span>}</span>
            <span className={styles.modelBody}><span className={styles.modelBrand}>{entry.brand}</span><strong className={styles.modelName}>{entry.model}</strong>{geometry && <small className={styles.geometry}>Заводская область<br/>{geometry}</small>}<small className={styles.connection}>{catalogConnectionHint(entry)}</small></span>
          </button>
        </li>;
      })}
    </ul> : <div className={styles.empty}>
      <Printer aria-hidden="true"/><strong>Модель не найдена</strong><p>Попробуйте короткое название или другого производителя. Также можно выбрать автоопределение и указать адрес принтера.</p><button type="button" onClick={resetFilters}>Показать все модели</button>
    </div>}

    <div className={styles.pagination}><ListPagination count={matches.length} page={paged.page} pageSize={PAGE_SIZE} onPageChange={paged.setPage} label="Страницы моделей принтеров"/></div>
    <p className={styles.note}>Для моделей без отдельной иллюстрации показан условный силуэт. Заводские размеры приведены для справки; настройки и доступные функции проверяются при подключении.</p>
  </section>;
}

