 return <div className={`wizard ${step===1?catalogStyles.wizardCatalog:''}`}><section className="wizardShell">
  <aside className="wizardAside"><img src={appIcon} alt="Klipper Farm"/><h1>Klipper Farm</h1><p>Локальный центр управления вашей фермой 3D‑принтеров.</p><div className="wizardSteps">{['Добро пожаловать','Подключение','Готово'].map((x,i)=><div key={x} className={i===step?'active':i<step?'done':''}><span>{i<step?'✓':i+1}</span><b>{x}</b></div>)}</div><small>Версия 1.14.5 · Transactional Core V13</small></aside>
  <main className="wizardMain"><header><div><span>ПЕРВЫЙ ЗАПУСК</span><b>Шаг {step+1} из 3</b></div><LanguageSelect compact/></header>
   {step===0&&<div className="wizardPage"><div className="wizardHeroIcon"><ShieldCheck/></div><h2>{t('setupIntro')}</h2><p>{t('setupIntroText')}</p><div className="wizardBenefits"><div><Wifi/><b>Локальная сеть</b><span>Без облачного аккаунта</span></div><div><Printer/><b>Несколько принтеров</b><span>Единая панель фермы</span></div><div><Database/><b>Данные на компьютере</b><span>История и настройки локально</span></div></div><button className="primary wizardNext" onClick={()=>setStep(1)}>{t('start')} →</button></div>}
   {step===1&&<div className="wizardPage wizardConnect">
    {choosingModel?<>
     <PrinterModelPicker selectedId={catalogModelId} onSelect={chooseModel} compact/>
     <div className="wizardActions"><button onClick={()=>{invalidateVerification();setStep(2)}}>{t('skip')}</button><button className="primary" onClick={()=>setChoosingModel(false)}>Продолжить {catalog?'с выбранной моделью':'с автоопределением'} →</button></div>
    </>:<>
     <div className="wizardHeroIcon"><Wifi/></div><h2>Подключите первый принтер</h2>
     <p>{catalog?catalogModelName(catalog):'Автоматическое определение модели'} · {catalog?catalogConnectionHint(catalog):'Требуется доступный Klipper/Moonraker'}</p>
     <button type="button" disabled={adding} onClick={()=>{invalidateVerification();setChoosingModel(true)}}>Выбрать другую модель</button>
     <p>{t('hostHelp')} Для K1C можно указать только IP — приложение проверит WebSocket на портах 80 и 7125.</p>
     <label>Название принтера<input disabled={adding} value={name} onChange={e=>{nameRevision.current++;setAutomaticName('');setName(e.target.value)}} placeholder="Определится автоматически"/></label>
     <label>Адрес Moonraker<input disabled={adding} value={host} onChange={e=>{setHost(e.target.value);invalidateVerification()}} placeholder="192.168.1.109 или 192.168.1.109:7125"/></label>
     <label>API Key — если включена авторизация<input disabled={adding} type="password" value={apiKey} onChange={e=>{setApiKey(e.target.value);invalidateVerification()}} placeholder="Можно оставить пустым"/></label>
     <small>Карточка сохраняет название модели. Рабочий профиль и доступные функции определяются при проверке подключения.</small>
     {checking&&<div className="wizardCheck checking"><LoaderCircle/> Проверяем Moonraker, конфигурацию и цифровой отпечаток…</div>}
     {detected&&<div className={`wizardCheck ${detected.ready?'ok':'warn'}`}><CheckCircle2/><div>
      <b>{detected.ready?'Подключение работает':'Moonraker доступен — Klipper ещё не готов'}</b>
      <span>{detected.status!=='matched'||detected.model==='custom'?detected.status==='ambiguous'?'Модель неоднозначна — будет сохранён безопасный пользовательский профиль':'Надёжная модель не определена — будет сохранён пользовательский профиль':`${detected.name} · уверенность: ${confidenceText(detected.confidence)} · ${detected.score} баллов`} · Klipper: {detected.klippyState} · {detected.latency} мс · проверок {detected.probeCoverage.successful}/{detected.probeCoverage.total}</span>
      {detected.probeWarnings.length>0&&<small>Неполный снимок: {detected.probeWarnings.join(', ')}. Принтер можно добавить — проверка повторится автоматически.</small>}
     </div></div>}
     {error&&<div className="wizardCheck error"><TriangleAlert/><span>{error}</span></div>}
     <div className="wizardActions"><button disabled={adding} onClick={()=>{invalidateVerification();setStep(2)}}>{t('skip')}</button><div>
      <button disabled={checking||adding||!host.trim()} onClick={verify}>{checking?'Проверка…':'Проверить подключение'}</button>
      <button className="primary" disabled={checking||adding||!detected?.reachable} onClick={add}>{adding?'Добавление…':'Добавить принтер'}</button>
     </div></div>
    </>}
   </div>}
   {step===2&&<div className="wizardPage"><div className="wizardHeroIcon success"><CheckCircle2/></div><h2>{t('done')}</h2><p>Klipper Farm готов к работе. Принтеры, очередь, камеры и статистика доступны на основной панели.</p><button className="primary wizardNext" onClick={finish}>{t('openFarm')} →</button></div>}
  </main>
 </section></div>;
}

import type { PrinterConfig, PrinterProfile } from '../types';
import { printerPresentationPreset } from './printerPresentation';
import { catalogModelArtwork, getCatalogModel } from './printerCatalog';
import enderKeArtwork from '../assets/ender-v3-ke-integrated-v2.png';
import enderSeArtwork from '../assets/ender-v3-se-neon-v114.png';
import k1cArtwork from '../assets/creality-k1c-clean-v1144.png';
import k1MaxArtwork from '../assets/creality-k1-max-neon-v114.png';
import adventurer5mArtwork from '../assets/flashforge-ad5m-clean-v1144.png';
import genericPrinterArtwork from '../assets/generic-klipper-printer.svg';

export const printerArtworkByPreset:Record<Exclude<PrinterProfile['preset'],undefined|'custom'>,string>={
  'ender3-v3-ke':enderKeArtwork,
  'ender3-v3-se':enderSeArtwork,
  'creality-k1c-2025':k1cArtwork,
  'creality-k1-max':k1MaxArtwork,
  'flashforge-ad5m':adventurer5mArtwork,
};

export const fallbackPrinterArtwork=genericPrinterArtwork;

export function printerArtwork(printer:Pick<PrinterConfig,'name'|'profile'|'modelSelection'|'imageData'|'catalogModelId'>){
  if(printer.imageData)return printer.imageData;
  if(printer.catalogModelId){
    const model=getCatalogModel(printer.catalogModelId);
    return model?catalogModelArtwork(model):genericPrinterArtwork;
  }
  const preset=printerPresentationPreset(printer);
  return preset?printerArtworkByPreset[preset]:genericPrinterArtwork;
}

import data from '../data/printerCatalog.json';
import type { KnownPrinterPreset } from '../types';
import enderKeArtwork from '../assets/ender-v3-ke-integrated-v2.png';
import enderSeArtwork from '../assets/ender-v3-se-neon-v114.png';
import k1cArtwork from '../assets/creality-k1c-clean-v1144.png';
import k1MaxArtwork from '../assets/creality-k1-max-neon-v114.png';
import adventurer5mArtwork from '../assets/flashforge-ad5m-clean-v1144.png';
import genericArtwork from '../assets/generic-klipper-printer.svg';

export interface PrinterCatalogModel {
  id:string;
  brand:string;
  model:string;
  aliases:string[];
  sourceUrl:string;
  nominalGeometry?:{x:number;y:number;z:number};
}

const normalize=(value:string)=>value.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().replace(/ё/g,'е').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const compact=(value:string)=>normalize(value).replace(/\s/g,'');
const brandOrder=['Creality','Anycubic','Elegoo','Flashforge','Sovol','Qidi','Bambu Lab','Prusa','Voron','RatRig'];
const order=(brand:string)=>{const index=brandOrder.findIndex(value=>compact(value)===compact(brand));return index<0?brandOrder.length:index};
const collator=new Intl.Collator('ru',{sensitivity:'base',numeric:true});
const featured=['crealityk1c','crealityk1max','crealityender3v3ke','crealityender3v3se','flashforgeadventurer5m','bambulaba1','bambulabp1s','prusaoriginalprusamk4'];
const featuredOrder=(entry:PrinterCatalogModel)=>{const index=featured.indexOf(compact(`${entry.brand} ${entry.model}`));return index<0?featured.length:index};

/** Factual model identities. Presence in this index does not attest transport support. */
export const PRINTER_CATALOG:readonly PrinterCatalogModel[]=(data.models as PrinterCatalogModel[]).slice().sort((a,b)=>featuredOrder(a)-featuredOrder(b)||order(a.brand)-order(b.brand)||collator.compare(a.brand,b.brand)||collator.compare(a.model,b.model));
const byId=new Map(PRINTER_CATALOG.map(entry=>[entry.id,entry]));
export const getCatalogModel=(id:string|undefined)=>id?byId.get(id):undefined;
export const catalogModelName=(entry:PrinterCatalogModel)=>normalize(entry.model).startsWith(normalize(entry.brand))?entry.model:`${entry.brand} ${entry.model}`;

const russianAliases:Record<string,string[]>={
  creality:['креалити','креалити3д'],anycubic:['эникубик','эникьюбик','аникубик'],elegoo:['элегу','элегоо'],flashforge:['флешфордж','флэшфордж'],sovol:['совол'],qidi:['куиди','киди'],bambulab:['бамбу','бамбулаб'],prusa:['пруса'],voron:['ворон'],ratrig:['ратриг'],ultimaker:['ультимейкер'],flyingbear:['флаингбир','летающий медведь'],artillery:['артиллери'],ankermake:['анкермейк']
};
const searchIndex=PRINTER_CATALOG.map(entry=>{
  const aliases=[...(russianAliases[compact(entry.brand)]??[]),...entry.aliases];
  if(normalize(entry.model).includes('ender'))aliases.push(entry.model.replace(/ender/ig,'эндер'));
  const text=normalize([entry.brand,entry.model,...aliases].join(' '));
  return {entry,text,compact:text.replace(/\s/g,'')};
});

export function catalogSearchModels(query:string,brand?:string):PrinterCatalogModel[]{
  const words=normalize(query).split(/\s+/).filter(Boolean);
  const selectedBrand=brand?compact(brand):undefined;
  return searchIndex.filter(item=>(!selectedBrand||compact(item.entry.brand)===selectedBrand)&&words.every(word=>item.text.includes(word)||item.compact.includes(word))).map(item=>item.entry);
}

/** Exact existing artwork families; never used to select a runtime driver. */
export function getCatalogPreset(entry:PrinterCatalogModel):KnownPrinterPreset|undefined{
  const brand=compact(entry.brand),model=compact(entry.model);
  if(brand==='creality'){
    if(model==='ender3v3ke')return 'ender3-v3-ke';
    if(model==='ender3v3se')return 'ender3-v3-se';
    if(model==='k1c'||model==='k1c2025')return 'creality-k1c-2025';
    if(model==='k1max')return 'creality-k1-max';
  }
  if(brand==='flashforge'&&(model==='adventurer5m'||model==='ad5m'))return 'flashforge-ad5m';
  return undefined;
}
const artwork:Record<KnownPrinterPreset,string>={'ender3-v3-ke':enderKeArtwork,'ender3-v3-se':enderSeArtwork,'creality-k1c-2025':k1cArtwork,'creality-k1-max':k1MaxArtwork,'flashforge-ad5m':adventurer5mArtwork};
export function catalogModelArtwork(entry:PrinterCatalogModel):string{const preset=getCatalogPreset(entry);return preset?artwork[preset]:genericArtwork}
export function catalogConnectionHint(entry:PrinterCatalogModel):string{
  const brand=compact(entry.brand);
  if(brand==='bambulab')return 'Штатное подключение Bambu пока не поддерживается';
  if(brand==='prusa')return 'Штатный PrusaLink пока не поддерживается';
  return 'Для подключения требуется доступный Klipper/Moonraker';
}

import type { PrinterConfig } from '../types';
import type { PrinterCatalogModel } from './printerCatalog';

const catalogName=(entry:PrinterCatalogModel)=>{
  const brand=entry.brand.trim(),model=entry.model.trim();
  return model.toLocaleLowerCase().startsWith(brand.toLocaleLowerCase())?model:`${brand} ${model}`.trim();
};

/**
 * A catalogue identity is separate from the printer's operational profile.
 * Choosing a card does not attest hardware or rewrite a working setup, even
 * when that card has a matching operational preset. Native profiles remain an
 * independent choice and are confirmed by the device probe.
 */
export function applyCatalogModel(config:PrinterConfig,entry?:PrinterCatalogModel):PrinterConfig{
  if(!entry)return {...config,catalogModelId:undefined};
  return {...config,catalogModelId:entry.id,name:config.name.trim()?config.name:catalogName(entry)};
}

import type { PrinterConfig, PrinterProfile } from '../types';
import { FLASHFORGE_5M_DISPLAY_NAME } from './printerDetection';
import { printerPresentationPreset } from './printerPresentation';
import { catalogModelName, getCatalogModel } from './printerCatalog';

const ipLike=/^(?:klipper\s+)?(?:https?:\/\/)?(?:\d{1,3}\.){3}\d{1,3}(?::\d+)?$/i;
const legacyFlashForge5mName=/^(?:(?:flashforge\s+)?(?:adventurer\s+5m|ad5m)|flashforge\s+5m)$/i;

export function normalizePrinterModelDisplayName(value:string|undefined,preset:PrinterProfile['preset']){
  const saved=(value??'').trim();
  if(preset==='flashforge-ad5m'&&(!saved||legacyFlashForge5mName.test(saved)))return FLASHFORGE_5M_DISPLAY_NAME;
  return saved;
}

export function printerDisplayName(printer:PrinterConfig,index=0){
  const saved=normalizePrinterModelDisplayName(printer.name,printer.profile?.preset);
  const generatedKlipperName=/^klipper(?:\s+printer)?(?:\s*[·-]\s*.+)?$/i.test(saved);
  if(saved&&!generatedKlipperName&&!ipLike.test(saved)&&saved!==printer.host)return saved;
  const catalog=getCatalogModel(printer.catalogModelId);
  if(catalog)return catalogModelName(catalog);
  const preset=printerPresentationPreset(printer);
  if(preset==='ender3-v3-ke')return 'Ender-3 V3 KE';
  if(preset==='ender3-v3-se')return 'Ender-3 V3 SE';
  if(preset==='creality-k1c-2025')return 'Creality K1C 2025';
  if(preset==='creality-k1-max')return 'Creality K1 Max';
  if(preset==='flashforge-ad5m')return FLASHFORGE_5M_DISPLAY_NAME;
  return `Принтер ${String(index+1).padStart(2,'0')}`;
}

export function uniquePrinterName(base:string,existingNames:string[]){
  const clean=base.trim()||'Klipper Printer';
  const used=new Set(existingNames.map(x=>x.trim().toLocaleLowerCase()));
  if(!used.has(clean.toLocaleLowerCase()))return clean;
  let number=2;
  while(used.has(`${clean} ${String(number).padStart(2,'0')}`.toLocaleLowerCase()))number++;
  return `${clean} ${String(number).padStart(2,'0')}`;
}

import type { KnownPrinterPreset, PrinterConfig } from '../types';

const knownPresets=new Set<KnownPrinterPreset>([
  'ender3-v3-ke','ender3-v3-se','creality-k1c-2025','creality-k1-max','flashforge-ad5m'
]);

// A probable classifier result may select the name/artwork, but the active
// operational profile remains custom until the user or high-confidence
// detection confirms it. Presentation must never unlock model-only commands.
export function printerPresentationPreset(printer:Pick<PrinterConfig,'name'|'profile'|'modelSelection'|'catalogModelId'>):KnownPrinterPreset|undefined{
  // An explicit catalogue model owns its displayed identity. Legacy brand/name
  // guesses must not label another Flashforge product as an Adventurer 5M.
  if(printer.catalogModelId)return undefined;
  const selected=printer.profile?.preset;
  if(selected&&selected!=='custom'&&knownPresets.has(selected))return selected;
  const detection=printer.modelSelection?.lastDetection;
  const detectedModel=detection?.model;
  if(
    printer.modelSelection?.mode==='automatic'&&
    detection?.status==='matched'&&
    (detection.decision==='confirmed'||detection.decision==='probable')&&
    detectedModel!==undefined&&detectedModel!=='custom'&&
    !(detection.conflicts?.length??0)&&
    knownPresets.has(detectedModel)
  )return detectedModel;
  const identity=printer.name.toLowerCase();
  if(identity.includes('k1 max')||identity.includes('k1-max')||identity.includes('k1max'))return 'creality-k1-max';
  if(identity.includes('k1c'))return 'creality-k1c-2025';
  if(identity.includes('ad5m')||identity.includes('adventurer 5m')||identity.includes('flashforge'))return 'flashforge-ad5m';
  if(identity.includes('v3-se')||identity.includes('v3 se'))return 'ender3-v3-se';
  if(identity.includes('v3-ke')||identity.includes('v3 ke'))return 'ender3-v3-ke';
  return undefined;
}

